package module1.programs;

public class If_Else_If_Block {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		int a=10;
		int b=20;
		
		if(a==10) 
		{
			System.out.println("if");
		}
		else if(b==20) 
		{
			System.out.println("Else if");
		}
		else 
		{
			System.out.println("else");
		}
	}

}
